        # Add multi-scale fractal-like oscillations
        for i in range(self.dim):
            freq = 2**((i % 5) + 1)
            result += 0.4 * np.sin(freq * x[i]) * np.cos(freq * x[i] * 0.7) * np.exp(-0.1 * x[i]**2)

