        for i in range(self.dim):
            if x[i] < 0:
                result += 0.3 * (x[i] + 5) * np.sin(20 * x[i])
            else:
                result += 0.3 * (5 - x[i]) * np.cos(15 * x[i])

        # Add irregular high-frequency noise with chaotic amplitude
        for i in range(self.dim):
